Here is the commit message:
sd-dhcp6-client: fix DUID data length passed to hexmem()

Fixes a bug introduced by 6b7d5b6eaf9029b88771ae0ba3cf3c95adb3c24d.

Here is the root cause:
The bug was caused by an incorrect validation of the DUID length, which was previously checked only to be greater than zero. This did not account for the actual structure size, leading to potential buffer overflows or incorrect data being processed when the DUID length was not properly set. The subsequent use of this incorrect length in the `hexmem()` function could result in memory access violations or incorrect data representation.

Here is the patch:

 int sd_dhcp6_client_duid_as_string(
                 sd_dhcp6_client *client,
                 char **duid) {
         _cleanup_free_ char *p = NULL, *s = NULL, *t = NULL;
         const char *v;
         int r;

         assert_return(client, -EINVAL);
-        assert_return(client->duid_len > 0, -ENODATA);
+        assert_return(client->duid_len > offsetof(struct duid, raw.data), -ENODATA);
         assert_return(duid, -EINVAL);

         v = duid_type_to_string(be16toh(client->duid.type));
         if (v) {
                 s = strdup(v);
                 if (!s)
                         return -ENOMEM;
         } else {
                 r = asprintf(&s, "%0x", client->duid.type);
                 if (r < 0)
                         return -ENOMEM;
         }

-        t = hexmem(&client->duid.raw.data, client->duid_len);
+        t = hexmem(client->duid.raw.data, client->duid_len - offsetof(struct duid, raw.data));
         if (!t)
                 return -ENOMEM;

         p = strjoin(s, ":", t);
         if (!p)
                 return -ENOMEM;

         *duid = TAKE_PTR(p);

         return 0;
 }



